//! Exact ShipShader GLSL literal from Ship.java's static initializer.
pub(crate) const SOURCE: &str = "\n    #version 150 core\n\n    layout(points) in;\n    layout(triangle_strip, max_vertices = 6) out;\n\n    out vec2 vTexCoord;\n\n    uniform mat4 transform;\n    uniform vec2 resolution;\n    uniform vec2 u_mouse;\n\n    uniform sampler2D pos;\n    uniform usampler2D valueMask;\n\n    void make013(const vec2 off[4], const uint s[4], const vec4 pos[4]) {\n        if ((s[1] & 5u) == 5u && (s[3] & 8u) != 0u) {\n            vTexCoord = off[0];\n            gl_Position = pos[0];\n            EmitVertex();\n\n            vTexCoord = off[1];\n            gl_Position = pos[1];\n            EmitVertex();\n\n            vTexCoord = off[3];\n            gl_Position = pos[3];\n            EmitVertex();\n            EndPrimitive();\n        }\n    }\n\n    void make132(const vec2 off[4], const uint s[4], const vec4 pos[4]) {\n        if ((s[1] & 3u) == 3u && (s[3] & 4u) != 0u) {\n            vTexCoord = off[1];\n            gl_Position = pos[1];\n            EmitVertex();\n\n            vTexCoord = off[3];\n            gl_Position = pos[3];\n            EmitVertex();\n\n            vTexCoord = off[2];\n            gl_Position = pos[2];\n            EmitVertex();\n            EndPrimitive();\n        }\n    }\n\n    void make012(const vec2 off[4], const uint s[4], const vec4 pos[4]) {\n        if ((s[1] & 6u) == 6u && (s[0] & 1u) != 0u) {\n            vTexCoord = off[0];\n            gl_Position = pos[0];\n            EmitVertex();\n\n            vTexCoord = off[1];\n            gl_Position = pos[1];\n            EmitVertex();\n\n            vTexCoord = off[2];\n            gl_Position = pos[2];\n            EmitVertex();\n            EndPrimitive();\n        }\n    }\n\n    void make032(const vec2 off[4], const uint s[4], const vec4 pos[4]) {\n        if ((s[3] & 12u) == 12u && (s[0] & 1u) != 0u) {\n            vTexCoord = off[0];\n            gl_Position = pos[0];\n            EmitVertex();\n\n            vTexCoord = off[3];\n            gl_Position = pos[3];\n            EmitVertex();\n\n            vTexCoord = off[2];\n            gl_Position = pos[2];\n            EmitVertex();\n            EndPrimitive();\n        }\n    }\n\n    void main()\n    {\n        ivec2 tex = ivec2(gl_in[0].gl_Position.xy);\n\n        ivec2 off[4] = ivec2[4](\n            ivec2(0, 1) + tex,\n            ivec2(0, 0) + tex,\n            ivec2(1, 1) + tex,\n            ivec2(1, 0) + tex\n        );\n\n        uint s[4] = uint[4](\n            texelFetch(valueMask, off[0], 0).z,\n            texelFetch(valueMask, off[1], 0).z,\n            texelFetch(valueMask, off[2], 0).z,\n            texelFetch(valueMask, off[3], 0).z\n        );\n\n        vec4 posVel[4] = vec4[4](\n            transform * vec4(texelFetch(pos, off[0], 0).xy + u_mouse, 0, 1),\n            transform * vec4(texelFetch(pos, off[1], 0).xy + u_mouse, 0, 1),\n            transform * vec4(texelFetch(pos, off[2], 0).xy + u_mouse, 0, 1),\n            transform * vec4(texelFetch(pos, off[3], 0).xy + u_mouse, 0, 1)\n        );\n\n        vec2 inv = vec2(1) / resolution;\n\n        vec2 tx[4] = vec2[4](\n            (off[0] + 0.5) * inv,\n            (off[1] + 0.5) * inv,\n            (off[2] + 0.5) * inv,\n            (off[3] + 0.5) * inv\n        );\n\n        if ((s[1] & 7u) == 7u && (s[0] & 1u) != 0u && (s[3] & 12u) == 12u) {\n            vTexCoord = tx[0];\n            gl_Position = posVel[0];\n            EmitVertex();\n\n            vTexCoord = tx[1];\n            gl_Position = posVel[1];\n            EmitVertex();\n\n            vTexCoord = tx[2];\n            gl_Position = posVel[2];\n            EmitVertex();\n\n            vTexCoord = tx[3];\n            gl_Position = posVel[3];\n            EmitVertex();\n            EndPrimitive();\n        } else {\n            make013(tx, s, posVel);\n            make132(tx, s, posVel);\n            make012(tx, s, posVel);\n            make032(tx, s, posVel);\n        }\n    }\n";
